import{_ as e,o as a,c as l,a2 as r}from"./chunks/framework.BQ1gajhD.js";const x=JSON.parse('{"title":"王府井步行街","description":"","frontmatter":{},"headers":[],"relativePath":"landmarks/wangfujing.md","filePath":"landmarks/wangfujing.md","lastUpdated":1787033866000}'),n={name:"landmarks/wangfujing.md"};function d(o,t,s,i,h,g){return a(),l("div",null,[...t[0]||(t[0]=[r('<h1 id="王府井步行街" tabindex="-1">王府井步行街 <a class="header-anchor" href="#王府井步行街" aria-label="Permalink to &quot;王府井步行街&quot;">​</a></h1><p><img src="https://images.unsplash.com/photo-1555529669-e69e7aa0ba9a?w=1200" alt="王府井步行街"></p><blockquote><p>&quot;金街王府井，百年商业老街。&quot;</p></blockquote><h2 id="简介" tabindex="-1">简介 <a class="header-anchor" href="#简介" aria-label="Permalink to &quot;简介&quot;">​</a></h2><p>王府井步行街位于北京市东城区，南起东长安街，北至中国美术馆，是北京最具代表性的商业街之一，素有&quot;金街&quot;之称。这里汇集了王府井百货、东方新天地、apm等大型商业体，也有王府井小吃街、老字号店铺和众多中华老字号品牌。白天人来人往，夜晚霓虹璀璨，是感受北京商业活力与都市风情的必到之地。</p><h2 id="基本信息" tabindex="-1">基本信息 <a class="header-anchor" href="#基本信息" aria-label="Permalink to &quot;基本信息&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">项目</th><th style="text-align:left;">内容</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>开放时间</strong></td><td style="text-align:left;">全天开放</td></tr><tr><td style="text-align:left;"><strong>门票价格</strong></td><td style="text-align:left;">免费</td></tr><tr><td style="text-align:left;"><strong>建议游玩</strong></td><td style="text-align:left;">2-3小时</td></tr><tr><td style="text-align:left;"><strong>最佳季节</strong></td><td style="text-align:left;">四季皆宜，夜晚最佳</td></tr><tr><td style="text-align:left;"><strong>交通方式</strong></td><td style="text-align:left;">地铁1号线王府井站或8号线金鱼胡同站</td></tr><tr><td style="text-align:left;"><strong>地址</strong></td><td style="text-align:left;">北京市东城区王府井大街</td></tr></tbody></table><h2 id="商业特色" tabindex="-1">商业特色 <a class="header-anchor" href="#商业特色" aria-label="Permalink to &quot;商业特色&quot;">​</a></h2><h3 id="大型购物中心" tabindex="-1">大型购物中心 <a class="header-anchor" href="#大型购物中心" aria-label="Permalink to &quot;大型购物中心&quot;">​</a></h3><p>东方新天地、apm、王府中環等现代商业体汇集国际品牌与高端购物体验，购物、餐饮、娱乐一应俱全。</p><h3 id="老字号与百年店铺" tabindex="-1">老字号与百年店铺 <a class="header-anchor" href="#老字号与百年店铺" aria-label="Permalink to &quot;老字号与百年店铺&quot;">​</a></h3><p>全聚德、盛锡福、内联升等老字号在此聚集，是购买北京特色商品和品尝传统美食的好去处。</p><h3 id="王府井小吃街" tabindex="-1">王府井小吃街 <a class="header-anchor" href="#王府井小吃街" aria-label="Permalink to &quot;王府井小吃街&quot;">​</a></h3><p>汇集各地小吃与北京特色美食，夜晚更是灯火通明、香气四溢，适合边走边逛边吃。</p><h2 id="游览攻略" tabindex="-1">游览攻略 <a class="header-anchor" href="#游览攻略" aria-label="Permalink to &quot;游览攻略&quot;">​</a></h2><h3 id="推荐路线" tabindex="-1">推荐路线 <a class="header-anchor" href="#推荐路线" aria-label="Permalink to &quot;推荐路线&quot;">​</a></h3><p><strong>半日路线</strong>：</p><p>王府井地铁站 → 王府井百货 → 东方新天地 → 王府井小吃街 → 百货大楼 → 东安市场</p><h3 id="实用贴士" tabindex="-1">实用贴士 <a class="header-anchor" href="#实用贴士" aria-label="Permalink to &quot;实用贴士&quot;">​</a></h3><ol><li><strong>交通</strong>：地铁1号线王府井站直达，晚间客流较大</li><li><strong>搭配</strong>：步行可达天安门、故宫，适合与中心区域串联游玩</li><li><strong>购物</strong>：既有高端商场也有老字号，可按预算自由选择</li><li><strong>餐饮</strong>：除了小吃街，各大商场内的餐饮选择也非常丰富</li></ol><h3 id="交通方式" tabindex="-1">交通方式 <a class="header-anchor" href="#交通方式" aria-label="Permalink to &quot;交通方式&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">方式</th><th style="text-align:left;">路线</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>地铁</strong></td><td style="text-align:left;">1号线王府井站，或8号线金鱼胡同站</td></tr><tr><td style="text-align:left;"><strong>公交</strong></td><td style="text-align:left;">王府井大街周边多路公交</td></tr><tr><td style="text-align:left;"><strong>打车</strong></td><td style="text-align:left;">定位&quot;王府井步行街&quot;即可</td></tr></tbody></table><h2 id="周边景点" tabindex="-1">周边景点 <a class="header-anchor" href="#周边景点" aria-label="Permalink to &quot;周边景点&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">景点</th><th style="text-align:center;">距离</th><th style="text-align:left;">特色</th></tr></thead><tbody><tr><td style="text-align:left;">天安门广场</td><td style="text-align:center;">步行15分钟</td><td style="text-align:left;">国家象征</td></tr><tr><td style="text-align:left;">故宫博物院</td><td style="text-align:center;">步行20分钟</td><td style="text-align:left;">明清皇宫</td></tr><tr><td style="text-align:left;">东交民巷</td><td style="text-align:center;">步行15分钟</td><td style="text-align:left;">西洋建筑群</td></tr><tr><td style="text-align:left;">前门大街</td><td style="text-align:center;">步行20分钟</td><td style="text-align:left;">老北京商业街</td></tr></tbody></table><h2 id="文化意义" tabindex="-1">文化意义 <a class="header-anchor" href="#文化意义" aria-label="Permalink to &quot;文化意义&quot;">​</a></h2><p>王府井步行街承载了北京商业百年变迁的记忆，从皇家御用集市到现代时尚商圈，它始终站在北京商业与文化的前沿，是观察北京城市活力的窗口。</p><hr><p><strong>📍 地址</strong>：北京市东城区王府井大街 <strong>🚇 地铁</strong>：1号线王府井站</p><p><strong>💡 Tips</strong>：王府井夜景更好看，建议安排傍晚前来，逛街后顺路去东交民巷或前门。</p>',29)])])}const c=e(n,[["render",d]]);export{x as __pageData,c as default};
